# -*- coding: utf-8 -*-
"""France / Sciences : CP, CE1, CE2（Questionner le monde du vivant, de la matière et des objets）"""
from fr_sci import H, nq, num


def f_volume(R):
    k = R.choice(["mlL", "Lml", "gkg", "kgg", "verres", "bouteilles"])
    if k == "mlL":
        L = R.choice([1, 2, 3, 4, 5, 6])
        return nq("Combien de millilitres y a-t-il dans %d L ?" % L, 1000 * L, [100 * L, 10 * L, L + 1000], "mL", "1 L = 1 000 mL, donc %d L = %s mL." % (L, num(1000 * L)))
    if k == "Lml":
        L = R.choice([2, 3, 4, 5, 7, 8])
        return nq("Une bassine contient %s mL d’eau. Combien de litres est-ce ?" % num(1000 * L), L, [10 * L, 100 * L, L * 1000 + 1], "L", "%s mL = %d L car 1 L = 1 000 mL." % (num(1000 * L), L))
    if k == "gkg":
        kg = R.choice([1, 2, 3, 4, 5, 6])
        return nq("Combien de grammes pèse un sac de %d kg ?" % kg, 1000 * kg, [100 * kg, 10 * kg, kg + 1000], "g", "1 kg = 1 000 g, donc %d kg = %s g." % (kg, num(1000 * kg)))
    if k == "kgg":
        kg = R.choice([2, 3, 4, 5, 6, 9])
        return nq("Un colis pèse %s g. Combien de kilogrammes est-ce ?" % num(1000 * kg), kg, [10 * kg, 100 * kg, kg * 1000 + 1], "kg", "%s g = %d kg." % (num(1000 * kg), kg))
    if k == "verres":
        v, n = R.choice([(200, 5), (250, 4), (100, 10), (500, 2), (200, 10), (250, 8)])
        return nq("Un verre contient %d mL. Combien de verres faut-il pour remplir une bouteille de %s mL ?" % (v, num(v * n)), n, [n + 1, n * 2, v // 10 if v // 10 != n else n + 3], "",
                  "%s : %d = %d verres." % (num(v * n), v, n))
    n = R.choice([2, 3, 4, 5, 6])
    return nq("On verse %d bouteilles d’un demi-litre dans un seau. Combien de litres d’eau y a-t-il ?" % (2 * n), n, [2 * n, 4 * n, n + 2], "L",
              "Deux demi-litres font 1 L, donc %d demi-litres font %d L." % (2 * n, n))


